// Обработка команд бота. Данные CRM приходят из предыдущей ноды,
// само сообщение берём из триггера.
const upd = $('Команда в Telegram').first().json;
const msg = upd.message;
if (!msg || !msg.text) return [];

const chatId = msg.chat.id;
const raw = msg.text.trim();
const cmd = raw.split(/[@\s]/)[0].toLowerCase();

const clients = ($input.first().json.clients) || [];

// Расписание студии — зеркало CLAUDE.md (0=Вс..6=Сб)
const SCHEDULE = {
  'Малыши':    [{ wd: 2, time: '18:00' }, { wd: 6, time: '12:00' }],
  'Младшие':   [{ wd: 1, time: '18:00' }, { wd: 3, time: '18:00' }, { wd: 5, time: '18:00' }, { wd: 6, time: '13:00' }],
  'Средние':   [{ wd: 5, time: '19:00' }],
  'Подростки': [{ wd: 3, time: '19:00' }, { wd: 6, time: '18:00' }],
};
const WD_RU = ['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];
const MONTHS_RU = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];

const msk = new Date(Date.now() + 3*3600*1000);
const todayStr = msk.toISOString().slice(0,10);
const wd = msk.getUTCDay();

function fmtDateRu(iso){
  if (!iso) return '—';
  const d = new Date(iso);
  return d.getUTCDate() + ' ' + MONTHS_RU[d.getUTCMonth()];
}

function needsRenewal(c){
  if (c.status !== 'bought') return false;
  if (!c.abEnd && !c.abNotifyDate) return false;
  // Галочка оплаты скрывает напоминание только пока абонемент ещё действует
  if (c.abRenewalPaid) {
    if (!c.abEnd) return false;
    if (c.abEnd >= todayStr) return false;
  }
  let d;
  if (c.abNotifyDate) d = new Date(c.abNotifyDate);
  else { d = new Date(c.abEnd); d.setDate(d.getDate()+1); }
  return d.toISOString().slice(0,10) <= todayStr;
}

function buildToday(){
  const trials = clients
    .filter(c => c.trial && c.trial.slice(0,10) === todayStr && (c.status==='trial' || c.status==='arrived'))
    .sort((a,b) => (a.trial||'').localeCompare(b.trial||''));
  const renewals = clients.filter(needsRenewal);
  const classesToday = Object.entries(SCHEDULE)
    .map(([g,slots]) => ({ g, slot: slots.find(s => s.wd === wd) }))
    .filter(x => x.slot);
  let t = `📋 <b>Сегодня ${WD_RU[wd]}, ${fmtDateRu(todayStr)}</b>\n`;
  if (classesToday.length) {
    t += `\n📅 <b>Занятия:</b>\n`;
    classesToday.forEach(x => { t += `• ${x.g} — ${x.slot.time}\n`; });
  } else {
    t += `\n📅 Занятий сегодня нет 😊\n`;
  }
  if (trials.length) {
    t += `\n🎯 <b>Пробные (${trials.length}):</b>\n`;
    trials.forEach(c => { t += `• ${c.trial.slice(11,16)} — ${c.name} (${c.group||'?'})\n`; });
  } else {
    t += `\n🎯 Пробных сегодня нет\n`;
  }
  if (renewals.length) {
    t += `\n💳 <b>Продления (${renewals.length}):</b>\n`;
    renewals.forEach(c => { t += `• ${c.abChild || c.name} — закончился ${fmtDateRu(c.abEnd)}\n`; });
  }
  return t;
}

function buildRenewals(){
  const renewals = clients.filter(needsRenewal);
  if (!renewals.length) return `💳 Продлений не ждём — все абонементы в порядке! 🌊`;
  let t = `💳 <b>Продления абонементов (${renewals.length}):</b>\n`;
  renewals.forEach(c => {
    t += `\n• <b>${c.abChild || c.name}</b>\n  ${c.name}${c.abGroup ? ' · ' + c.abGroup : (c.group ? ' · ' + c.group : '')}\n  закончился ${fmtDateRu(c.abEnd)}${c.phone ? '\n  📞 ' + c.phone : ''}\n`;
  });
  return t;
}

function buildTrials(){
  const future = clients
    .filter(c => c.status === 'trial' && c.trial && c.trial.slice(0,10) >= todayStr)
    .sort((a,b) => (a.trial||'').localeCompare(b.trial||''));
  if (!future.length) return `🎯 Записей на пробные пока нет`;
  let t = `🎯 <b>Ближайшие пробные (${future.length}):</b>\n`;
  let lastDay = '';
  future.forEach(c => {
    const day = c.trial.slice(0,10);
    if (day !== lastDay) {
      const d = new Date(day + 'T00:00');
      t += `\n<b>${WD_RU[d.getUTCDay()]}, ${fmtDateRu(day)}:</b>\n`;
      lastDay = day;
    }
    t += `• ${c.trial.slice(11,16)} — ${c.name} (${c.group||'?'})\n`;
  });
  return t;
}

let text = null;
if (cmd === '/id') {
  text = `🆔 Chat ID этого чата: <code>${chatId}</code>\nВпиши его в настройки в воркфлоу «Утренний дайджест» (нода «Собрать сообщения»).`;
} else if (cmd === '/start' || cmd === '/help' || cmd === '/помощь') {
  text = `🌊 <b>Бот студии «Движение Океана»</b>\n\nКоманды:\n/today — задачи на сегодня (занятия, пробные, продления)\n/trials — ближайшие записи на пробные\n/renewals — кому пора продлить абонемент\n/id — узнать chat id этого чата (для настройки)`;
} else if (cmd === '/today' || cmd === '/сегодня') {
  text = buildToday();
} else if (cmd === '/renewals' || cmd === '/продления') {
  text = buildRenewals();
} else if (cmd === '/trials' || cmd === '/пробные') {
  text = buildTrials();
} else {
  return []; // не команда — молчим (важно для групповых чатов)
}

return [{ json: { chatId, text } }];
